28	    const at::Tensor& x, const at::Tensor& h_res, const at::Tensor& h_out, const at::Tensor& h_post)
29	{
30	    // x shape: (B, S, n, D) or (T, n, D)
31	    // h_res shape: (B, S, n, n) or (T, n, n)
32	    // h_out shape: (B, S, D) or (T, D)
33	    // h_post shape: (B, S, n) or (T, n)
34	    // output shape: (B, S, n, D) or (T, n, D)
35	
36	    const auto x_dim = x.dim();
37	    c10::TensorOptions outputOptions = x.options().dtype(x.dtype());
38	
39	    auto num_heads = x.sym_size(x_dim - DIM_2); // D: xDim - 2
40	    auto h_dim = x.sym_size(x_dim - DIM_1);     // D: xDim - 1
41	
42	    at::Tensor output = at::Tensor();
43	    c10::SmallVector<c10::SymInt, DIM_2> outputSize = {x.sym_size(DIM_0), 0};
44	
45	    if (x_dim == NUM_4) {
46	        // B, S, n, D
47	        outputSize[DIM_1] = x.sym_size(DIM_1); // sequence
48	        outputSize.push_back(num_heads);       // attach num_heads(DIM_3)
49	    } else if (x_dim == DIM_3) {
50	        // T, n, D
51	        outputSize[DIM_1] = num_heads;
52	    }
53	    outputSize.push_back(h_dim); // h_dim is always the last
54	
55	    output = at::empty_symint(outputSize, outputOptions);
56	    return output;
57	}
