62	{
63	    // x shape: (B, S, n, D)
64	    // h_res shape: (B, S, n, n)
65	    // h_out shape: (B, S, D)
66	    // h_post shape: (B, S, n)
67	
68	    // 输出shape: (B, S, n, D)
