/*!
 * \file npu_ai_infra_manifold_constrained_hyper_connection_post.cpp
 * \brief
 */

#include <iostream>
#include <torch/library.h>
#include "../../../../csrc_base/ops_common.h"

namespace {
constexpr int64_t NUM_4 = 4;
};

namespace custom {
using namespace at_npu::native;

at::Tensor construct_mhc_post_returns(
    const at::Tensor& x, const at::Tensor& h_res, const at::Tensor& h_out, const at::Tensor& h_post)
{
    // x shape: (B, S, n, D) or (T, n, D)
    // h_res shape: (B, S, n, n) or (T, n, n)
    // h_out shape: (B, S, D) or (T, D)
    // h_post shape: (B, S, n) or (T, n)
    // output shape: (B, S, n, D) or (T, n, D)

    const auto x_dim = x.dim();
    c10::TensorOptions outputOptions = x.options().dtype(x.dtype());

    auto num_heads = x.sym_size(x_dim - DIM_2); // D: xDim - 2
    auto h_dim = x.sym_size(x_dim - DIM_1);     // D: xDim - 1

    at::Tensor output = at::Tensor();
    c10::SmallVector<c10::SymInt, DIM_2> outputSize = {x.sym_size(DIM_0), 0};

    if (x_dim == NUM_4) {
        // B, S, n, D
        outputSize[DIM_1] = x.sym_size(DIM_1); // sequence
        outputSize.push_back(num_heads);       // attach num_heads(DIM_3)
    } else if (x_dim == DIM_3) {
        // T, n, D
        outputSize[DIM_1] = num_heads;
    }
    outputSize.push_back(h_dim); // h_dim is always the last

    output = at::empty_symint(outputSize, outputOptions);
    return output;
}

// 为NPU设备实现正向接口
at::Tensor npu_ai_infra_manifold_constrained_hyper_connection_post_npu(
    const at::Tensor& x, const at::Tensor& h_res, const at::Tensor& h_out, const at::Tensor& h_post)
{
    // x shape: (B, S, n, D)
    // h_res shape: (B, S, n, n)
    // h_out shape: (B, S, D)
    // h_post shape: (B, S, n)

    // 输出shape: (B, S, n, D)
    at::Tensor output = construct_mhc_post_returns(x, h_res, h_out, h_post);

    EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPost, x, h_res, h_out, h_post, output);

    return output;
}

// 为META设备实现正向接口
at::Tensor npu_ai_infra_manifold_constrained_hyper_connection_post_meta(
    const at::Tensor& x, const at::Tensor& h_res, const at::Tensor& h_out, const at::Tensor& h_post)
{
    at::Tensor output = construct_mhc_post_returns(x, h_res, h_out, h_post);
    return output;
}

// 为NPU设备注册正向实现
TORCH_LIBRARY_IMPL(custom, PrivateUse1, m)
{
    m.impl(
        "npu_ai_infra_manifold_constrained_hyper_connection_post",
        &custom::npu_ai_infra_manifold_constrained_hyper_connection_post_npu);
}

// 为META设备注册正向实现
TORCH_LIBRARY_IMPL(custom, Meta, m)
{
    m.impl(
        "npu_ai_infra_manifold_constrained_hyper_connection_post",
        &custom::npu_ai_infra_manifold_constrained_hyper_connection_post_meta);
}

} // namespace custom

