14	#include "../../../../csrc_base/ops_common.h"
15	
16	using torch::autograd::AutogradContext;
17	using torch::autograd::Function;
18	using variable_list = std::vector<at::Tensor>;
19	
20	namespace custom {
21	    const static int64_t DIM_0 = 0;
22	    const static int64_t DIM_1 = 1;
23	    const static int64_t DIM_2 = 2;
24	    const static int64_t DIM_3 = 3;
25	    const static int64_t BSND_DIMS = 4;
26	    const static int64_t TND_DIMS = 4;
27	
28	    using namespace at_npu::native;
29	
30	    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
31	    construct_manifold_constrained_hyper_connection_pre_output_tensor(
32	        const at::Tensor &x, const at::Tensor &phi)
33	    {
34	        c10::TensorOptions hInOptions = x.options().dtype(x.dtype());
35	        c10::TensorOptions hOptions = x.options().dtype(at::kFloat);
36	        auto matK = phi.sym_size(DIM_0);  // 符号整数
37	
38	        at::Tensor outHin;
39	        at::Tensor outHpost;
40	        at::Tensor outHres;
41	        at::Tensor outInvRms;
42	        at::Tensor mmRes;
43	        at::Tensor outHPre;
44	
45	        if (x.dim() == 4) { // 4 : 当x为4维时
46	            auto batch        = x.sym_size(DIM_0);
47	            auto sequence     = x.sym_size(DIM_1);
48	            auto numsResidual = x.sym_size(DIM_2);
49	            auto dimen        = x.sym_size(DIM_3);
50	
51	            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> outHinSize    = {batch, sequence, dimen};
52	            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> outHpostSize  = {batch, sequence, numsResidual};
53	            c10::SmallVector<c10::SymInt, BSND_DIMS>     outHresSize   = {batch, sequence, numsResidual, numsResidual};
54	            c10::SmallVector<c10::SymInt, BSND_DIMS - 2> outInvRmsSize = {batch, sequence};   // 2 : InvRms比x少2维
55	            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> mmResSize     = {batch, sequence, matK};
56	            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> outHPreSize   = {batch, sequence, numsResidual};
57	
58	            outHin    = at::empty_symint(outHinSize,    hInOptions);
59	            outHpost  = at::empty_symint(outHpostSize,  hOptions);
60	            outHres   = at::empty_symint(outHresSize,   hOptions);
61	            outInvRms = at::empty_symint(outInvRmsSize, hOptions);
62	            mmRes     = at::empty_symint(mmResSize,     hOptions);
63	            outHPre   = at::empty_symint(outHPreSize,   hOptions);
64	        } else {
65	            auto t            = x.sym_size(DIM_0);
66	            auto numsResidual = x.sym_size(DIM_1);
67	            auto dimen        = x.sym_size(DIM_2);
68	
69	            c10::SmallVector<c10::SymInt, TND_DIMS - 1> outHinSize    = {t, dimen};
70	            c10::SmallVector<c10::SymInt, TND_DIMS - 1> outHpostSize  = {t, numsResidual};
71	            c10::SmallVector<c10::SymInt, TND_DIMS>     outHresSize   = {t, numsResidual, numsResidual};
72	            c10::SmallVector<c10::SymInt, TND_DIMS - 2> outInvRmsSize = {t}; // 2 : InvRms比x少2维
73	            c10::SmallVector<c10::SymInt, TND_DIMS - 1> mmResSize     = {t, matK};
74	            c10::SmallVector<c10::SymInt, TND_DIMS - 1> outHPreSize   = {t, numsResidual};
75	
76	            outHin    = at::empty_symint(outHinSize,    hInOptions);
77	            outHpost  = at::empty_symint(outHpostSize,  hOptions);
78	            outHres   = at::empty_symint(outHresSize,   hOptions);
79	            outInvRms = at::empty_symint(outInvRmsSize, hOptions);
80	            mmRes     = at::empty_symint(mmResSize,     hOptions);
81	            outHPre   = at::empty_symint(outHPreSize,   hOptions);
82	        }
83	
84	        return std::make_tuple(outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
85	    }
86	    
87	    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
88	    npu_manifold_constrained_hyper_connection_pre(
89	        const at::Tensor &x, const at::Tensor &phi,
90	        const at::Tensor &alpha, const at::Tensor &bias,
91	        const c10::optional<at::Tensor> &gamma, int64_t out_flag,
92	        double norm_eps, double hc_eps)
93	    {
94	        TORCH_CHECK(x.numel() > 0, "Tensor x is empty.");
95	        TORCH_CHECK(phi.numel() > 0, "Tensor phi is empty.");
96	        TORCH_CHECK(alpha.numel() > 0, "Tensor alpha is empty.");
97	        TORCH_CHECK(bias.numel() > 0, "Tensor bias is empty.");
98	
99	        auto manifold_constrained_hyper_connection_pre_output =
100	            custom::construct_manifold_constrained_hyper_connection_pre_output_tensor(x, phi);
101	
102	        at::Tensor outHin = std::get<0>(manifold_constrained_hyper_connection_pre_output);
103	        at::Tensor outHpost = std::get<1>(manifold_constrained_hyper_connection_pre_output);
104	        at::Tensor outHres = std::get<2>(manifold_constrained_hyper_connection_pre_output);
105	        at::Tensor outInvRms = std::get<3>(manifold_constrained_hyper_connection_pre_output);
106	        at::Tensor mmRes = std::get<4>(manifold_constrained_hyper_connection_pre_output);
107	        at::Tensor outHPre = std::get<5>(manifold_constrained_hyper_connection_pre_output);
108	
109	        EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPre, x, phi, alpha, bias, gamma, out_flag,
110	                        norm_eps, hc_eps, outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
111	
112	        return std::make_tuple(outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
113	    }
114	
115	    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
116	    npu_manifold_constrained_hyper_connection_pre_grad_npu(
117	        const at::Tensor &x, const at::Tensor &phi, const at::Tensor &alpha, const at::Tensor &h_in_grad,
118	        const at::Tensor &h_post_grad, const at::Tensor &h_comb_before_grad, const at::Tensor &inv_rms,
119	        const at::Tensor &mm_res, const at::Tensor &h_pre, const at::Tensor &h_post,
120	        const c10::optional<at::Tensor> &gamma, double hc_eps, const c10::optional<at::Tensor> &grad_x_post)
121	    {
122	        TORCH_CHECK(x.numel() > 0, "Tensor x is empty.");
123	        TORCH_CHECK(phi.numel() > 0, "Tensor phi is empty.");
124	        TORCH_CHECK(alpha.numel() > 0, "Tensor alpha is empty.");
125	        TORCH_CHECK(h_in_grad.numel()  > 0, "Tensor h_in_grad dims is empty");
126	        TORCH_CHECK(h_post_grad.numel() > 0, "Tensor h_post_grad is empty.");
127	        TORCH_CHECK(h_comb_before_grad.numel() > 0, "Tensor h_comb_before_grad is empty.");
128	        TORCH_CHECK(inv_rms.numel() > 0, "Tensor inv_rms is empty.");
129	        TORCH_CHECK(mm_res.numel() > 0, "Tensor mm_res is empty.");
130	        TORCH_CHECK(h_pre.numel() > 0, "Tensor h_pre is empty.");
131	        TORCH_CHECK(h_post.numel() > 0, "Tensor h_post is empty.");
132	
133	        c10::TensorOptions xGradOptions = h_in_grad.options().dtype(h_in_grad.dtype());
134	        c10::TensorOptions fp32Options = h_in_grad.options().dtype(at::kFloat);
135	
136	        at::Tensor xGrad;
137	        at::Tensor hcWeightGrad;
138	        at::Tensor alphaGrad;
139	        at::Tensor biasPostGrad;
140	        at::Tensor gammaGrad;
141	
142	        if (h_in_grad.dim() == 3) { // 3 : 当h_in_grad的维度为3
143	            // BSND格式: h_in_grad [B,S,D], h_post_grad [B,S,N], h_comb_before_grad [B,S,N,N]
144	            auto batch = h_in_grad.size(DIM_0);
145	            auto sequence = h_in_grad.size(DIM_1);
146	            auto dimen = h_in_grad.size(DIM_2);
147	            auto numsResidual = h_post_grad.size(DIM_2);
148	
149	            c10::SmallVector<int64_t, BSND_DIMS> xGradSize = {batch, sequence, numsResidual, dimen};
150	            // 2 : hcWeightGrad 的维度 [2*N + N*N, N*D]
151	            c10::SmallVector<int64_t, 2> hcWeightGradSize = {(2 * numsResidual) + (numsResidual * numsResidual),
152	                                                             numsResidual * dimen};
153	            c10::SmallVector<int64_t, 1> alphaGradSize = {3}; // alpha的元素个数为3
154	            // 2 : biasPostGrad 的维度为[2*N + N*N]
155	            c10::SmallVector<int64_t, 1> biasPostGradSize = {(2 * numsResidual) + (numsResidual * numsResidual)};
156	            c10::SmallVector<int64_t, 1> gammaGradSize = {numsResidual, dimen};
157	
158	            xGrad = at::empty(xGradSize, xGradOptions);
159	            hcWeightGrad = at::empty(hcWeightGradSize, fp32Options);
160	            alphaGrad = at::empty(alphaGradSize, fp32Options);
161	            biasPostGrad = at::empty(biasPostGradSize, fp32Options);
162	            gammaGrad = at::empty(gammaGradSize, fp32Options);
163	        } else {
164	            // TND格式: h_in_grad [T,D], h_post_grad [T,N], h_comb_before_grad [T,N,N]
165	            auto t = h_in_grad.size(DIM_0);
166	            auto dimen = h_in_grad.size(DIM_1);
167	            auto numsResidual = h_post_grad.size(DIM_1);
168	
169	            c10::SmallVector<int64_t, TND_DIMS> xGradSize = {t, numsResidual, dimen};
170	            // 2 : hcWeightGrad 的维度 [2*N + N*N, N*D]
171	            c10::SmallVector<int64_t, 2> hcWeightGradSize = {(2 * numsResidual) + (numsResidual * numsResidual),
172	                                                             numsResidual * dimen};
173	            c10::SmallVector<int64_t, 1> alphaGradSize = {3}; // alpha的元素个数为3
174	            // 2 : biasPostGrad 的维度为[2*N + N*N]
175	            c10::SmallVector<int64_t, 1> biasPostGradSize = {(2 * numsResidual) + (numsResidual * numsResidual)};
176	            c10::SmallVector<int64_t, 1> gammaGradSize = {numsResidual, dimen};
177	
178	            xGrad = at::empty(xGradSize, xGradOptions);
179	            hcWeightGrad = at::empty(hcWeightGradSize, fp32Options);
180	            alphaGrad = at::empty(alphaGradSize, fp32Options);
181	            biasPostGrad = at::empty(biasPostGradSize, fp32Options);
182	            gammaGrad = at::empty(gammaGradSize, fp32Options);
183	        }
184	
185	        static const auto getWorkspaceSizeFuncAddr =
186	            GetOpApiFuncAddr("aclnnAiInfraManifoldConstrainedHyperConnectionPreGradV2GetWorkspaceSize");
187	        static const auto opApiFuncAddr = GetOpApiFuncAddr("aclnnAiInfraManifoldConstrainedHyperConnectionPreGradV2");
188	        if (getWorkspaceSizeFuncAddr && opApiFuncAddr) {
189	            EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPreGradV2, x, phi, alpha, h_in_grad,
190	                            h_post_grad, h_comb_before_grad, inv_rms, mm_res, h_pre, h_post, gamma, grad_x_post, hc_eps,
191	                            xGrad, hcWeightGrad, alphaGrad, biasPostGrad, gammaGrad);
192	        } else {
193	            EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPreGrad, x, phi, alpha, h_in_grad,
194	                            h_post_grad, h_comb_before_grad, inv_rms, mm_res, h_pre, h_post, gamma, hc_eps, xGrad,
195	                            hcWeightGrad, alphaGrad, biasPostGrad, gammaGrad);
196	        }
197	
198	        return std::make_tuple(xGrad, hcWeightGrad, alphaGrad, biasPostGrad, gammaGrad);
199	    }
200	
201	    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
202	    npu_manifold_constrained_hyper_connection_pre_meta(
203	        const at::Tensor &x, const at::Tensor &phi,
204	        const at::Tensor &alpha, const at::Tensor &bias,
205	        const c10::optional<at::Tensor> &gamma, int64_t out_flag,
206	        double norm_eps, double hc_eps)
207	    {
208	        auto manifold_constrained_hyper_connection_pre_output =
209	            custom::construct_manifold_constrained_hyper_connection_pre_output_tensor(x, phi);
210	
211	        at::Tensor outHin = std::get<0>(manifold_constrained_hyper_connection_pre_output);
212	        at::Tensor outHpost = std::get<1>(manifold_constrained_hyper_connection_pre_output);
213	        at::Tensor outHres = std::get<2>(manifold_constrained_hyper_connection_pre_output);
214	        at::Tensor outInvRms = std::get<3>(manifold_constrained_hyper_connection_pre_output);
215	        at::Tensor mmRes = std::get<4>(manifold_constrained_hyper_connection_pre_output);
216	        at::Tensor outHPre = std::get<5>(manifold_constrained_hyper_connection_pre_output);
217	
218	        if (out_flag == 0) {
219	            outInvRms = at::empty_symint({0}, x.options().dtype(at::kFloat));
220	            mmRes = at::empty_symint({0}, x.options().dtype(at::kFloat));
221	            outHPre = at::empty_symint({0}, x.options().dtype(at::kFloat));
222	        }
223	        return std::make_tuple(outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
224	    }
225	
226	    class ManifoldConstrainedHyperConnectionPreFunction
227	        : public torch::autograd::Function<ManifoldConstrainedHyperConnectionPreFunction> {
228	    public:
229	        static variable_list forward(
230	            AutogradContext *ctx,
231	            const at::Tensor &x,
232	            const at::Tensor &phi,
233	            const at::Tensor &alpha,
234	            const at::Tensor &bias,
235	            const c10::optional<at::Tensor> &gamma,
236	            int64_t out_flag,
237	            double norm_eps,
238	            double hc_eps)
239	        {
240	            at::AutoDispatchBelowADInplaceOrView guard;
241	
242	            static auto op = torch::Dispatcher::singleton()
243	                .findSchemaOrThrow("custom::npu_manifold_constrained_hyper_connection_pre", "")
244	                .typed<decltype(npu_manifold_constrained_hyper_connection_pre)>();
245	
246	            auto outputs = op.call(x, phi, alpha, bias, gamma, out_flag, norm_eps, hc_eps);
247	            auto outHin = std::get<0>(outputs);
248	            auto outHpost = std::get<1>(outputs);
249	            auto outHres = std::get<2>(outputs);
250	            auto outInvRms = std::get<3>(outputs);
251	            auto outmmRes = std::get<4>(outputs);
252	            auto outHPre = std::get<5>(outputs);
253	    
254	            // 保存反向需要的非tensor变量/输入到上下文
255	            ctx->saved_data["hc_eps"] = hc_eps;
256	
257	            ctx->save_for_backward({
258	                x, phi, alpha, gamma.value_or(at::Tensor()),
259	                outHpost.detach(), outInvRms.detach(), outmmRes.detach(), outHPre.detach()
260	            });
261	
262	            // 保存 outHin 和 outHres 的 shape 用于 backward 创建零张量
263	            ctx->saved_data["outHin_shape"] = outHin.sym_sizes();
264	            ctx->saved_data["outHres_shape"] = outHres.sym_sizes();
265	
266	            return {outHin, outHpost, outHres, outInvRms, outmmRes, outHPre};
267	        }
268	
269	        static variable_list backward(AutogradContext *ctx, variable_list grad_outputs)
270	        {
271	            auto saved = ctx->get_saved_variables();
272	            at::Tensor x = saved[0];     // 0 : x 参数的索引为0
273	            at::Tensor phi = saved[1];   // 1 : phi 参数的索引为1
274	            at::Tensor alpha = saved[2]; // 2 : alpha 参数的索引为2
275	            // 3 : gamma参数的索引为3
276	            c10::optional<at::Tensor> gamma = saved[3].defined() ? c10::optional<at::Tensor>(saved[3]) : c10::nullopt;
277	
278	            at::Tensor outHpost = saved[4];  // 4 : outHpost 参数的索引为4
279	            at::Tensor outInvRms = saved[5]; // 5 : outInvRms 参数的索引为5
280	            at::Tensor outmmRes = saved[6];  // 6 : outmmRes 参数的索引为6
281	            at::Tensor outHPre = saved[7];   // 7 : outHPre 参数的索引为7
282	
283	            double hcEps = ctx->saved_data["hc_eps"].toDouble();
284	
285	            // 获取 shape 信息
286	            std::vector<int64_t> outHinShape = ctx->saved_data["outHin_shape"].toIntVector();
287	            std::vector<int64_t> outHresShape = ctx->saved_data["outHres_shape"].toIntVector();
288	
289	            // 创建 backward 的 grad tensor，缺省为零
290	            at::Tensor hInGrad = grad_outputs.size() > 0 && grad_outputs[0].defined()
291	                ? grad_outputs[0].contiguous()
292	                : at::zeros(outHinShape, x.options());
293	            at::Tensor hPostGrad = grad_outputs.size() > 1 && grad_outputs[1].defined()
294	                ? grad_outputs[1].contiguous()
295	                : at::zeros_like(outHpost);
296	            at::Tensor hCombBeforeGrad = grad_outputs.size() > 2 && grad_outputs[2].defined()
297	                ? grad_outputs[2].contiguous()
298	                : at::zeros(outHresShape, outHpost.options());
299	
300	            static auto op = torch::Dispatcher::singleton()
301	                .findSchemaOrThrow("custom::npu_manifold_constrained_hyper_connection_pre_grad", "")
302	                .typed<decltype(npu_manifold_constrained_hyper_connection_pre_grad_npu)>();
303	
304	            auto grads = op.call(x, phi, alpha, hInGrad, hPostGrad,
305	            hCombBeforeGrad, outInvRms, outmmRes, outHPre, outHpost, gamma, hcEps, c10::nullopt);
306	            at::Tensor xGrad = std::get<0>(grads);
307	            at::Tensor hcWeightGrad = std::get<1>(grads);
308	            at::Tensor alphaGrad = std::get<2>(grads);
309	            at::Tensor biasPostGrad = std::get<3>(grads);
310	            at::Tensor gammaGrad = std::get<4>(grads);
311	
312	            return {
313	                xGrad,
314	                hcWeightGrad,
315	                alphaGrad,
316	                biasPostGrad,
