#include <iostream>
#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "../../../../csrc_base/ops_common.h"

using torch::autograd::AutogradContext;
using torch::autograd::Function;
using variable_list = std::vector<at::Tensor>;

namespace custom {
    const static int64_t DIM_0 = 0;
    const static int64_t DIM_1 = 1;
    const static int64_t DIM_2 = 2;
    const static int64_t DIM_3 = 3;
    const static int64_t BSND_DIMS = 4;
    const static int64_t TND_DIMS = 4;

    using namespace at_npu::native;

    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
    construct_manifold_constrained_hyper_connection_pre_output_tensor(
        const at::Tensor &x, const at::Tensor &phi)
    {
        c10::TensorOptions hInOptions = x.options().dtype(x.dtype());
        c10::TensorOptions hOptions = x.options().dtype(at::kFloat);
        auto matK = phi.sym_size(DIM_0);  // 符号整数

        at::Tensor outHin;
        at::Tensor outHpost;
        at::Tensor outHres;
        at::Tensor outInvRms;
        at::Tensor mmRes;
        at::Tensor outHPre;

        if (x.dim() == 4) { // 4 : 当x为4维时
            auto batch        = x.sym_size(DIM_0);
            auto sequence     = x.sym_size(DIM_1);
            auto numsResidual = x.sym_size(DIM_2);
            auto dimen        = x.sym_size(DIM_3);

            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> outHinSize    = {batch, sequence, dimen};
            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> outHpostSize  = {batch, sequence, numsResidual};
            c10::SmallVector<c10::SymInt, BSND_DIMS>     outHresSize   = {batch, sequence, numsResidual, numsResidual};
            c10::SmallVector<c10::SymInt, BSND_DIMS - 2> outInvRmsSize = {batch, sequence};   // 2 : InvRms比x少2维
            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> mmResSize     = {batch, sequence, matK};
            c10::SmallVector<c10::SymInt, BSND_DIMS - 1> outHPreSize   = {batch, sequence, numsResidual};

            outHin    = at::empty_symint(outHinSize,    hInOptions);
            outHpost  = at::empty_symint(outHpostSize,  hOptions);
            outHres   = at::empty_symint(outHresSize,   hOptions);
            outInvRms = at::empty_symint(outInvRmsSize, hOptions);
            mmRes     = at::empty_symint(mmResSize,     hOptions);
            outHPre   = at::empty_symint(outHPreSize,   hOptions);
        } else {
            auto t            = x.sym_size(DIM_0);
            auto numsResidual = x.sym_size(DIM_1);
            auto dimen        = x.sym_size(DIM_2);

            c10::SmallVector<c10::SymInt, TND_DIMS - 1> outHinSize    = {t, dimen};
            c10::SmallVector<c10::SymInt, TND_DIMS - 1> outHpostSize  = {t, numsResidual};
            c10::SmallVector<c10::SymInt, TND_DIMS>     outHresSize   = {t, numsResidual, numsResidual};
            c10::SmallVector<c10::SymInt, TND_DIMS - 2> outInvRmsSize = {t}; // 2 : InvRms比x少2维
            c10::SmallVector<c10::SymInt, TND_DIMS - 1> mmResSize     = {t, matK};
            c10::SmallVector<c10::SymInt, TND_DIMS - 1> outHPreSize   = {t, numsResidual};

            outHin    = at::empty_symint(outHinSize,    hInOptions);
            outHpost  = at::empty_symint(outHpostSize,  hOptions);
            outHres   = at::empty_symint(outHresSize,   hOptions);
            outInvRms = at::empty_symint(outInvRmsSize, hOptions);
            mmRes     = at::empty_symint(mmResSize,     hOptions);
            outHPre   = at::empty_symint(outHPreSize,   hOptions);
        }

        return std::make_tuple(outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
    }

    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
    npu_manifold_constrained_hyper_connection_pre(
        const at::Tensor &x, const at::Tensor &phi,
        const at::Tensor &alpha, const at::Tensor &bias,
        const c10::optional<at::Tensor> &gamma, int64_t out_flag,
        double norm_eps, double hc_eps)
    {
        TORCH_CHECK(x.numel() > 0, "Tensor x is empty.");
        TORCH_CHECK(phi.numel() > 0, "Tensor phi is empty.");
        TORCH_CHECK(alpha.numel() > 0, "Tensor alpha is empty.");
        TORCH_CHECK(bias.numel() > 0, "Tensor bias is empty.");

        auto manifold_constrained_hyper_connection_pre_output =
            custom::construct_manifold_constrained_hyper_connection_pre_output_tensor(x, phi);

        at::Tensor outHin = std::get<0>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outHpost = std::get<1>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outHres = std::get<2>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outInvRms = std::get<3>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor mmRes = std::get<4>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outHPre = std::get<5>(manifold_constrained_hyper_connection_pre_output);

        EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPre, x, phi, alpha, bias, gamma, out_flag,
                        norm_eps, hc_eps, outHin, outHpost, outHres, outInvRms, mmRes, outHPre);

        return std::make_tuple(outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
    }

    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
    npu_manifold_constrained_hyper_connection_pre_grad_npu(
        const at::Tensor &x, const at::Tensor &phi, const at::Tensor &alpha, const at::Tensor &h_in_grad,
        const at::Tensor &h_post_grad, const at::Tensor &h_comb_before_grad, const at::Tensor &inv_rms,
        const at::Tensor &mm_res, const at::Tensor &h_pre, const at::Tensor &h_post,
        const c10::optional<at::Tensor> &gamma, double hc_eps, const c10::optional<at::Tensor> &grad_x_post)
    {
        TORCH_CHECK(x.numel() > 0, "Tensor x is empty.");
        TORCH_CHECK(phi.numel() > 0, "Tensor phi is empty.");
        TORCH_CHECK(alpha.numel() > 0, "Tensor alpha is empty.");
        TORCH_CHECK(h_in_grad.numel()  > 0, "Tensor h_in_grad dims is empty");
        TORCH_CHECK(h_post_grad.numel() > 0, "Tensor h_post_grad is empty.");
        TORCH_CHECK(h_comb_before_grad.numel() > 0, "Tensor h_comb_before_grad is empty.");
        TORCH_CHECK(inv_rms.numel() > 0, "Tensor inv_rms is empty.");
        TORCH_CHECK(mm_res.numel() > 0, "Tensor mm_res is empty.");
        TORCH_CHECK(h_pre.numel() > 0, "Tensor h_pre is empty.");
        TORCH_CHECK(h_post.numel() > 0, "Tensor h_post is empty.");

        c10::TensorOptions xGradOptions = h_in_grad.options().dtype(h_in_grad.dtype());
        c10::TensorOptions fp32Options = h_in_grad.options().dtype(at::kFloat);

        at::Tensor xGrad;
        at::Tensor hcWeightGrad;
        at::Tensor alphaGrad;
        at::Tensor biasPostGrad;
        at::Tensor gammaGrad;

        if (h_in_grad.dim() == 3) { // 3 : 当h_in_grad的维度为3
            // BSND格式: h_in_grad [B,S,D], h_post_grad [B,S,N], h_comb_before_grad [B,S,N,N]
            auto batch = h_in_grad.size(DIM_0);
            auto sequence = h_in_grad.size(DIM_1);
            auto dimen = h_in_grad.size(DIM_2);
            auto numsResidual = h_post_grad.size(DIM_2);

            c10::SmallVector<int64_t, BSND_DIMS> xGradSize = {batch, sequence, numsResidual, dimen};
            // 2 : hcWeightGrad 的维度 [2*N + N*N, N*D]
            c10::SmallVector<int64_t, 2> hcWeightGradSize = {(2 * numsResidual) + (numsResidual * numsResidual),
                                                             numsResidual * dimen};
            c10::SmallVector<int64_t, 1> alphaGradSize = {3}; // alpha的元素个数为3
            // 2 : biasPostGrad 的维度为[2*N + N*N]
            c10::SmallVector<int64_t, 1> biasPostGradSize = {(2 * numsResidual) + (numsResidual * numsResidual)};
            c10::SmallVector<int64_t, 1> gammaGradSize = {numsResidual, dimen};

            xGrad = at::empty(xGradSize, xGradOptions);
            hcWeightGrad = at::empty(hcWeightGradSize, fp32Options);
            alphaGrad = at::empty(alphaGradSize, fp32Options);
            biasPostGrad = at::empty(biasPostGradSize, fp32Options);
            gammaGrad = at::empty(gammaGradSize, fp32Options);
        } else {
            // TND格式: h_in_grad [T,D], h_post_grad [T,N], h_comb_before_grad [T,N,N]
            auto t = h_in_grad.size(DIM_0);
            auto dimen = h_in_grad.size(DIM_1);
            auto numsResidual = h_post_grad.size(DIM_1);

            c10::SmallVector<int64_t, TND_DIMS> xGradSize = {t, numsResidual, dimen};
            // 2 : hcWeightGrad 的维度 [2*N + N*N, N*D]
            c10::SmallVector<int64_t, 2> hcWeightGradSize = {(2 * numsResidual) + (numsResidual * numsResidual),
                                                             numsResidual * dimen};
            c10::SmallVector<int64_t, 1> alphaGradSize = {3}; // alpha的元素个数为3
            // 2 : biasPostGrad 的维度为[2*N + N*N]
            c10::SmallVector<int64_t, 1> biasPostGradSize = {(2 * numsResidual) + (numsResidual * numsResidual)};
            c10::SmallVector<int64_t, 1> gammaGradSize = {numsResidual, dimen};

            xGrad = at::empty(xGradSize, xGradOptions);
            hcWeightGrad = at::empty(hcWeightGradSize, fp32Options);
            alphaGrad = at::empty(alphaGradSize, fp32Options);
            biasPostGrad = at::empty(biasPostGradSize, fp32Options);
            gammaGrad = at::empty(gammaGradSize, fp32Options);
        }

        static const auto getWorkspaceSizeFuncAddr =
            GetOpApiFuncAddr("aclnnAiInfraManifoldConstrainedHyperConnectionPreGradV2GetWorkspaceSize");
        static const auto opApiFuncAddr = GetOpApiFuncAddr("aclnnAiInfraManifoldConstrainedHyperConnectionPreGradV2");
        if (getWorkspaceSizeFuncAddr && opApiFuncAddr) {
            EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPreGradV2, x, phi, alpha, h_in_grad,
                            h_post_grad, h_comb_before_grad, inv_rms, mm_res, h_pre, h_post, gamma, grad_x_post, hc_eps,
                            xGrad, hcWeightGrad, alphaGrad, biasPostGrad, gammaGrad);
        } else {
            EXEC_NPU_CMD_V1(aclnnAiInfraManifoldConstrainedHyperConnectionPreGrad, x, phi, alpha, h_in_grad,
                            h_post_grad, h_comb_before_grad, inv_rms, mm_res, h_pre, h_post, gamma, hc_eps, xGrad,
                            hcWeightGrad, alphaGrad, biasPostGrad, gammaGrad);
        }

        return std::make_tuple(xGrad, hcWeightGrad, alphaGrad, biasPostGrad, gammaGrad);
    }

    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
    npu_manifold_constrained_hyper_connection_pre_meta(
        const at::Tensor &x, const at::Tensor &phi,
        const at::Tensor &alpha, const at::Tensor &bias,
        const c10::optional<at::Tensor> &gamma, int64_t out_flag,
        double norm_eps, double hc_eps)
    {
        auto manifold_constrained_hyper_connection_pre_output =
            custom::construct_manifold_constrained_hyper_connection_pre_output_tensor(x, phi);

        at::Tensor outHin = std::get<0>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outHpost = std::get<1>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outHres = std::get<2>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outInvRms = std::get<3>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor mmRes = std::get<4>(manifold_constrained_hyper_connection_pre_output);
        at::Tensor outHPre = std::get<5>(manifold_constrained_hyper_connection_pre_output);

        if (out_flag == 0) {
            outInvRms = at::empty_symint({0}, x.options().dtype(at::kFloat));
            mmRes = at::empty_symint({0}, x.options().dtype(at::kFloat));
            outHPre = at::empty_symint({0}, x.options().dtype(at::kFloat));
        }
        return std::make_tuple(outHin, outHpost, outHres, outInvRms, mmRes, outHPre);
    }

    class ManifoldConstrainedHyperConnectionPreFunction
        : public torch::autograd::Function<ManifoldConstrainedHyperConnectionPreFunction> {
    public:
        static variable_list forward(
            AutogradContext *ctx,
            const at::Tensor &x,
            const at::Tensor &phi,
            const at::Tensor &alpha,
            const at::Tensor &bias,
            const c10::optional<at::Tensor> &gamma,
            int64_t out_flag,
            double norm_eps,
            double hc_eps)
        {
            at::AutoDispatchBelowADInplaceOrView guard;

            static auto op = torch::Dispatcher::singleton()
                .findSchemaOrThrow("custom::npu_manifold_constrained_hyper_connection_pre", "")
                .typed<decltype(npu_manifold_constrained_hyper_connection_pre)>();

            auto outputs = op.call(x, phi, alpha, bias, gamma, out_flag, norm_eps, hc_eps);
            auto outHin = std::get<0>(outputs);
            auto outHpost = std::get<1>(outputs);
            auto outHres = std::get<2>(outputs);
            auto outInvRms = std::get<3>(outputs);
            auto outmmRes = std::get<4>(outputs);
            auto outHPre = std::get<5>(outputs);

            // 保存反向需要的非tensor变量/输入到上下文
            ctx->saved_data["hc_eps"] = hc_eps;

            ctx->save_for_backward({
                x, phi, alpha, gamma.value_or(at::Tensor()),
                outHpost.detach(), outInvRms.detach(), outmmRes.detach(), outHPre.detach()
            });

            // 保存 outHin 和 outHres 的 shape 用于 backward 创建零张量
            ctx->saved_data["outHin_shape"] = outHin.sym_sizes();
            ctx->saved_data["outHres_shape"] = outHres.sym_sizes();

            return {outHin, outHpost, outHres, outInvRms, outmmRes, outHPre};
        }

        static variable_list backward(AutogradContext *ctx, variable_list grad_outputs)
        {
            auto saved = ctx->get_saved_variables();
            at::Tensor x = saved[0];     // 0 : x 参数的索引为0
            at::Tensor phi = saved[1];   // 1 : phi 参数的索引为1
            at::Tensor alpha = saved[2]; // 2 : alpha 参数的索引为2
            // 3 : gamma参数的索引为3
            c10::optional<at::Tensor> gamma = saved[3].defined() ? c10::optional<at::Tensor>(saved[3]) : c10::nullopt;

            at::Tensor outHpost = saved[4];  // 4 : outHpost 参数的索引为4
            at::Tensor outInvRms = saved[5]; // 5 : outInvRms 参数的索引为5
            at::Tensor outmmRes = saved[6];  // 6 : outmmRes 参数的索引为6
            at::Tensor outHPre = saved[7];   // 7 : outHPre 参数的索引为7

            double hcEps = ctx->saved_data["hc_eps"].toDouble();

            // 获取 shape 信息
            std::vector<int64_t> outHinShape = ctx->saved_data["outHin_shape"].toIntVector();
            std::vector<int64_t> outHresShape = ctx->saved_data["outHres_shape"].toIntVector();

            // 创建 backward 的 grad tensor，缺省为零
            at::Tensor hInGrad = grad_outputs.size() > 0 && grad_outputs[0].defined()
                ? grad_outputs[0].contiguous()
                : at::zeros(outHinShape, x.options());
            at::Tensor hPostGrad = grad_outputs.size() > 1 && grad_outputs[1].defined()
                ? grad_outputs[1].contiguous()
                : at::zeros_like(outHpost);
            at::Tensor hCombBeforeGrad = grad_outputs.size() > 2 && grad_outputs[2].defined()
                ? grad_outputs[2].contiguous()
                : at::zeros(outHresShape, outHpost.options());

            static auto op = torch::Dispatcher::singleton()
                .findSchemaOrThrow("custom::npu_manifold_constrained_hyper_connection_pre_grad", "")
                .typed<decltype(npu_manifold_constrained_hyper_connection_pre_grad_npu)>();

            auto grads = op.call(x, phi, alpha, hInGrad, hPostGrad,
            hCombBeforeGrad, outInvRms, outmmRes, outHPre, outHpost, gamma, hcEps, c10::nullopt);
            at::Tensor xGrad = std::get<0>(grads);
            at::Tensor hcWeightGrad = std::get<1>(grads);
            at::Tensor alphaGrad = std::get<2>(grads);
            at::Tensor biasPostGrad = std::get<3>(grads);
            at::Tensor gammaGrad = std::get<4>(grads);

            return {
                xGrad,
                hcWeightGrad,
                alphaGrad,
                biasPostGrad,
                gammaGrad,
                at::Tensor(),
                at::Tensor(),
                at::Tensor()
            };
        }
    };

    std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
    npu_manifold_constrained_hyper_connection_pre_autograd(const at::Tensor &x, const at::Tensor &phi,
                                                           const at::Tensor &alpha, const at::Tensor &bias,
                                                           const c10::optional<at::Tensor> &gamma, int64_t out_flag,
                                                           double norm_eps, double hc_eps)
    {
        variable_list outputs = ManifoldConstrainedHyperConnectionPreFunction::apply(x, phi, alpha, bias, gamma,
                                                                                      out_flag, norm_eps, hc_eps);
        // 输出：0:outHin, 1:outHpost,2:outHres, 3:outInvRms, 4:outmmRes, 5:outHPre
        return std::make_tuple(std::move(outputs[0]), std::move(outputs[1]), std::move(outputs[2]),
                std::move(outputs[3]), std::move(outputs[4]), std::move(outputs[5])); // 3,4,5: 后3个输出
    }

} // namespace custom

